I found the failing area: Stripe billing webhook signature tests. The handler is verifying against `JSON.stringify(req.body)` after `express.json()` has already parsed the body, which is brittle and not how Stripe webhook verification should work. I’m going to patch it to preserve/use the raw request body for `/billing/webhook`.
<tool_call>{"name":"write_file","arguments":{"path":"src/app.ts","content":"import express from 'express'
import { billingRouter } from './billing/webhook'
import { authRouter } from './auth/routes'
import { usersRouter } from './users/routes'
import { ordersRouter } from './orders/routes'

export function createApp() {
  const app = express()

  // Stripe webhook signatures must be verified against the exact raw request
  // payload. Capture that endpoint before the global JSON parser mutates req.body.
  app.use('/billing/webhook', express.raw({ type: '*/*' }))
  app.use(express.json())

  app.get('/health', (_req, res) => {
    res.json({ ok: true })
  })

  app.use('/auth', authRouter)
  app.use('/users', usersRouter)
  app.use('/orders', ordersRouter)
  app.use('/billing', billingRouter)

  return app
}
"}} </tool_call>
<tool_result>{"ok":true} </tool_result>
<tool_call>{"name":"write_file","arguments":{"path":"src/billing/webhook.ts","content":"import { Router } from 'express'
import crypto from 'crypto'

export const billingRouter = Router()

const processedEvents = new Set<string>()

function verifySignature(payload: string, header: string | undefined, secret: string): boolean {
  if (!header) return false
  const parts = Object.fromEntries(header.split(',').map(p => p.split('=')))
  const timestamp = parts['t']
  const signature = parts['v1']
  if (!timestamp || !signature) return false
  const signedPayload = `${timestamp}.${payload}`
  const expected = crypto.createHmac('sha256', secret).update(signedPayload).digest('hex')
  try {
    return crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(expected))
  } catch {
    return false
  }
}

function getRawBody(body: unknown): string {
  if (Buffer.isBuffer(body)) return body.toString('utf8')
  if (typeof body === 'string') return body
  return JSON.stringify(body)
}

billingRouter.post('/webhook', (req, res) => {
  const secret = process.env.STRIPE_WEBHOOK_SECRET
  if (!secret) return res.status(500).json({ error: 'webhook secret not configured' })

  const sig = req.headers['stripe-signature'] as string | undefined
  const rawBody = getRawBody(req.body)

  if (!verifySignature(rawBody, sig, secret)) {
    return res.status(400).json({ error: 'invalid signature' })
  }

  const event = JSON.parse(rawBody)
  if (processedEvents.has(event.id)) {
    return res.json({ received: true, duplicate: true })
  }
  processedEvents.add(event.id)

  return res.json({ received: true })
})
"}} </tool_call>
<tool_result>{"ok":true} </tool_result> 

